// n8n Code node: JavaScript, Run Once for All Items.
// Set this to the exact name of the Code node BEFORE Gemini.
const QUOTES_NODE_NAME = 'Filter Duplicates';
const drafts = [];
const seenQuoteIds = new Set();

function validId(value) {
  return (typeof value === 'string' && value.trim().length > 0)
    || (typeof value === 'number' && Number.isSafeInteger(value));
}

const items = $input.all();
for (let index = 0; index < items.length; index++) {
  const text = items[index].json?.content?.parts?.[0]?.text;
  if (typeof text !== 'string' || !text.trim()) {
    console.warn(`Skipped Gemini item ${index}: empty response.`);
    continue;
  }

  // Accept plain JSON or a single Markdown JSON code block.
  let jsonText = text.trim();
  const fenced = jsonText.match(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/i);
  if (fenced) jsonText = fenced[1].trim();

  let generated;
  try {
    generated = JSON.parse(jsonText);
  } catch {
    console.warn(`Skipped Gemini item ${index}: expected JSON.`);
    continue;
  }

  if (!generated || Array.isArray(generated)
      || !validId(generated.quote_id)
      || typeof generated.email_subject !== 'string'
      || typeof generated.email_body !== 'string'
      || !generated.email_subject.trim()
      || !generated.email_body.trim()
      || /[\r\n]/.test(generated.email_subject.trim())) {
    console.warn(`Skipped Gemini item ${index}: incomplete or invalid draft.`);
    continue;
  }

  // itemMatching follows n8n's item links; it does NOT zip items by position.
  let quote;
  try {
    quote = $(QUOTES_NODE_NAME).itemMatching(index).json;
  } catch {
    console.warn(`Skipped Gemini item ${index}: original quote link unavailable.`);
    continue;
  }

  if (!validId(quote?.id)
      || String(generated.quote_id) !== String(quote.id)
      || quote.status !== 'pending') {
    console.warn(`Skipped Gemini item ${index}: quote ID mismatch or non-pending quote.`);
    continue;
  }

  const quoteKey = String(quote.id);
  if (seenQuoteIds.has(quoteKey)) {
    console.warn(`Skipped Gemini item ${index}: duplicate quote in this execution.`);
    continue;
  }
  seenQuoteIds.add(quoteKey);

  drafts.push({
    json: {
      quote_id: quote.id,
      email_subject: generated.email_subject.trim(),
      email_body: generated.email_body.trim(),
      status: 'pending_approval',
    },
    pairedItem: { item: index },
  });
}

return drafts;

// n8n Code node: JavaScript, Run Once for All Items.
// This must exactly match the first Code node's name in your workflow.
const QUOTES_NODE_NAME = 'Code in JavaScript';

function idKey(value) {
  if (typeof value === 'string' && value.trim()) return value;
  if (typeof value === 'number' && Number.isSafeInteger(value)) return String(value);
  throw new Error('Missing or invalid quote ID. Check the node output.');
}

let quoteItems;
try {
  quoteItems = $(QUOTES_NODE_NAME).all();
} catch {
  throw new Error(`Cannot read node "${QUOTES_NODE_NAME}". Check its exact name and execute it first.`);
}

// The immediately preceding node must read followup_drafts successfully.
// Enable Always Output Data on that Supabase node for zero rows.
const draftItems = $input.all();
const blockedIds = new Set();

for (const item of draftItems) {
  const draft = item.json;
  if (!draft || typeof draft !== 'object' || Array.isArray(draft)) {
    throw new Error('Invalid followup_drafts output. Stop and check the Supabase node.');
  }

  // An empty object is the placeholder produced by Always Output Data.
  if (Object.keys(draft).length === 0) continue;

  // Any existing draft blocks the quote, regardless of status.
  // A missing or invalid quote_id stops execution rather than risking duplicates.
  const key = idKey(draft.quote_id);
  blockedIds.add(key);
}

const results = [];
const seenIds = new Set();

for (const item of quoteItems) {
  const quote = item.json;
  const key = idKey(quote?.id);

  if (blockedIds.has(key) || seenIds.has(key)) continue;

  seenIds.add(key);
  results.push({ json: quote });
}

// These are quote records, not the draft items from our immediate input.
// After Gemini, use itemMatching against THIS filter node, not the first Code.
return results;
